def test_promotion_target_contract_rejects_mapping_and_order_mutations(
    monkeypatch,
) -> None:
    module = load_checker()
    original = module.PROMOTION_PROOF_TARGET_CONTRACTS
    expected_ids = (
        *module.PROMOTION_TLAPS_TARGET_IDS,
        *module.PROMOTION_CROSS_TOOL_TARGET_IDS,
    )
    assert tuple(target.obligation_id for target in original) == expected_ids
    assert [target.kind for target in original] == ["tlaps"] * 9 + [
        "cross_tool"
    ] * 3
    assert all(target.expected_obligations is None for target in original)
    entries = module._promotion_target_entries()
    for entry in entries:
        assert entry["start_line"] <= entry["end_line"]
        assert entry["invocation"][:3] == [
            "--toolbox",
            str(entry["start_line"]),
            str(entry["end_line"]),
        ]
        assert "--strict" in entry["invocation"]
        assert "--nofp" in entry["invocation"]

    mutants = (
        original[:-1],
        (*original[:-1], original[0]),
        (original[1], original[0], *original[2:]),
        (
            replace(
                original[0],
                provider_module="SumeragiV2AsyncTemporalClosureProofs",
            ),
            *original[1:],
        ),
        (
            *original[:-1],
            replace(
                original[-1],
                theorem=(
                    module.CROSS_TOOL_REFINEMENT_BY_ID[
                        original[-1].obligation_id
                    ].ledger_symbol
                ),
            ),
        ),
    )
    expected_fragments = (
        "canonical 9 + 3 order",
        "duplicate",
        "canonical 9 + 3 order",
        "provider must be",
        "exact cross-tool bridge",
    )
    for mutant, fragment in zip(mutants, expected_fragments):
        monkeypatch.setattr(module, "PROMOTION_PROOF_TARGET_CONTRACTS", mutant)
        assert any(
            fragment in error
            for error in module._promotion_target_contract_errors()
        )
    monkeypatch.setattr(module, "PROMOTION_PROOF_TARGET_CONTRACTS", original)


def test_promotion_target_evidence_rejects_every_range_log_and_digest_mutation(
    tmp_path: Path,
) -> None:
    module = load_checker()
    assert module.EVIDENCE_SCHEMA_VERSION == 3
    ledger = complete_ledger(module)
    formal_dir, _, evidence = build_test_evidence(module, tmp_path)

    def errors_for(mutant):
        return module._release_evidence_errors(
            ledger,
            mutant,
            formal_dir=formal_dir,
            root_dir=tmp_path,
        )

    assert errors_for(evidence) == []

    omitted = copy.deepcopy(evidence)
    omitted["promotion_targets"].pop()
    assert any("canonical 9 + 3 order" in error for error in errors_for(omitted))

    duplicated = copy.deepcopy(evidence)
    duplicated["promotion_targets"][-1] = copy.deepcopy(
        duplicated["promotion_targets"][0]
    )
    duplicate_errors = errors_for(duplicated)
    assert any("must not repeat" in error for error in duplicate_errors)

    reordered = copy.deepcopy(evidence)
    reordered["promotion_targets"][0], reordered["promotion_targets"][1] = (
        reordered["promotion_targets"][1],
        reordered["promotion_targets"][0],
    )
    assert any("canonical 9 + 3 order" in error for error in errors_for(reordered))

    field_mutations = {
        "kind": "cross_tool",
        "ledger_module": "MutatedLedgerModule",
        "provider_module": "SumeragiV2AsyncTemporalClosureProofs",
        "theorem": "EffectiveLockBodyAcquisitionProductionRefinementObligation",
        "start_line": evidence["promotion_targets"][0]["start_line"] + 1,
        "end_line": evidence["promotion_targets"][0]["end_line"] + 1,
        "source": "formal/sumeragi_v2/MutatedProvider.tla",
        "source_sha256": "0" * 64,
        "proof_span_sha256": "1" * 64,
        "invocation_sha256": "2" * 64,
        "expected_obligations": (
            1
            if evidence["promotion_targets"][0]["expected_obligations"] is None
            else evidence["promotion_targets"][0]["expected_obligations"] + 1
        ),
    }
    for field, value in field_mutations.items():
        mutant = copy.deepcopy(evidence)
        mutant["promotion_targets"][0][field] = value
        assert any(
            f"wrong {field}" in error for error in errors_for(mutant)
        )

    zero = copy.deepcopy(evidence)
    zero["promotion_targets"][0]["obligations_proved"] = 0
    assert any("no positive proved count" in error for error in errors_for(zero))

    forged_count = copy.deepcopy(evidence)
    forged_count["promotion_targets"][0]["obligations_proved"] = 999
    assert any("does not match log" in error for error in errors_for(forged_count))

    weakened_invocation = copy.deepcopy(evidence)
    weakened_invocation["promotion_targets"][0]["invocation"].remove("--nofp")
    assert any(
        "wrong invocation" in error for error in errors_for(weakened_invocation)
    )

    wrong_schema = copy.deepcopy(evidence)
    wrong_schema["schema_version"] = 2
    assert any(
        "proof evidence schema_version must equal 3" in error
        for error in errors_for(wrong_schema)
    )

    swapped_log = copy.deepcopy(evidence)
    first, second = swapped_log["promotion_targets"][:2]
    first["log"] = second["log"]
    assert any("must use log" in error for error in errors_for(swapped_log))

    stale_target_log_digest = copy.deepcopy(evidence)
    stale_target_log_digest["promotion_targets"][0]["log_sha256"] = "4" * 64
    assert any(
        "target log digest mismatch" in error
        for error in errors_for(stale_target_log_digest)
    )

    stale_target_ledger = copy.deepcopy(evidence)
    stale_target_ledger["promotion_targets"][0]["ledger_sha256"] = "5" * 64
    assert any(
        "not bound to the current proof ledger" in error
        for error in errors_for(stale_target_ledger)
    )

    stale_ledger = copy.deepcopy(evidence)
    stale_ledger["ledger_sha256"] = "2" * 64
    for entry in stale_ledger["modules"]:
        entry["ledger_sha256"] = "2" * 64
    for entry in stale_ledger["promotion_targets"]:
        entry["ledger_sha256"] = "2" * 64
    stale_errors = errors_for(stale_ledger)
    assert any("byte-exact proof ledger" in error for error in stale_errors)

    stale_source = copy.deepcopy(evidence)
    stale_source["promotion_targets"][0]["source_manifest_sha256"] = "3" * 64
    assert any(
        "current source manifest" in error for error in errors_for(stale_source)
    )

    # Even a semantically identical ledger rewrite invalidates every first-pass
    # transcript because promotion is a byte-level source change.
    (formal_dir / "proof_coverage.json").write_text(
        json.dumps(ledger, separators=(",", ":")) + "\n",
        encoding="utf-8",
    )
    assert any(
        "byte-exact proof ledger" in error for error in errors_for(evidence)
    )


def test_cross_tool_status_is_fail_closed_and_production_only() -> None:
    module = load_checker()
    ledger = module.load_ledger()

    assert ledger["schema_version"] == module.LEDGER_SCHEMA_VERSION == 2
    assert ledger["status_values"] == list(module.STATUS_VALUES)
    assert [
        len(contract.claims)
        for contract in module.CROSS_TOOL_REFINEMENT_CONTRACTS
    ] == [4, 7, 6]
    assert module._cross_tool_contract_errors() == []
    production_call_sites = [
        call_site
        for contract in module.CROSS_TOOL_REFINEMENT_CONTRACTS
        for claim in contract.claims
        for call_site in (
            *claim.production_call_sites,
            *(
                call_site
                for kernel in claim.supplemental_kernels
                for call_site in kernel.production_call_sites
            ),
        )
    ]
    linked_consumers = [
        consumer
        for contract in module.CROSS_TOOL_REFINEMENT_CONTRACTS
        for claim in contract.claims
        for consumer in claim.linked_consumers
    ]
    gate_call_count = sum(
        call_site.gate_call_count for call_site in production_call_sites
    )
    assert gate_call_count == 33
    assert len(linked_consumers) == 6
    assert gate_call_count + len(linked_consumers) == 39
    sealed_production_seams = sum(
        call_site.gate_call_count
        for call_site in production_call_sites
        if call_site.item_token_sha256 is not None
    ) + sum(
        consumer.item_token_sha256 is not None
        for consumer in linked_consumers
    )
    assert sealed_production_seams == 37
    promotion_errors = module._cross_tool_promotion_contract_errors(
        module.CROSS_TOOL_REFINEMENT_CONTRACTS
    )
    assert promotion_errors == []
    canonical_contracts = module.CROSS_TOOL_REFINEMENT_CONTRACTS
    first = canonical_contracts[0]
    tautological = module.CrossToolObligationContract(
        obligation_id=first.obligation_id,
        module=first.module,
        ledger_symbol=first.ledger_symbol,
        tla_theorem=first.tla_theorem,
        tla_statement=(
            "ProductionEffectiveLockBodyAcquisitionRefinement => "
            "ProductionEffectiveLockBodyAcquisitionRefinement"
        ),
        claims=first.claims,
    )
    module.CROSS_TOOL_REFINEMENT_CONTRACTS = (
        tautological,
        *canonical_contracts[1:],
    )
    assert any(
        "must imply its exact ledger theorem symbol" in error
        for error in module._cross_tool_contract_errors()
    )
    module.CROSS_TOOL_REFINEMENT_CONTRACTS = canonical_contracts
    by_id = {obligation["id"]: obligation for obligation in ledger["obligations"]}
    assert all(
        by_id[obligation_id]["status"] == "specified_unproved"
        for obligation_id in module.CROSS_TOOL_REFINEMENT_BY_ID
    )
    assert module._cross_tool_evidence_errors(
        ledger,
        {},
        tlaps_evidence=None,
        verus_evidence=None,
    ) == [
        "cross-tool evidence is forbidden when no obligation is cross_tool_proved"
    ]
    with pytest.raises(ValueError, match="no cross_tool_proved obligations"):
        module.build_cross_tool_evidence(
            ledger,
            tlaps_evidence={},
            verus_evidence={},
        )

    forged = copy.deepcopy(ledger)
    next(
        obligation
        for obligation in forged["obligations"]
        if obligation["id"] == "dual-quorum-definition"
    )["status"] = "cross_tool_proved"
    errors = module.validate_ledger(forged, check_retired_paths=False).errors
    assert any(
        "uses cross_tool_proved outside the reviewed production refinement inventory"
        in error
        for error in errors
    )

    tlaps_only = copy.deepcopy(ledger)
    next(
        obligation
        for obligation in tlaps_only["obligations"]
        if obligation["id"]
        == "effective-lock-body-acquisition-production-refinement"
    )["status"] = "tlaps_proved"
    errors = module.validate_ledger(tlaps_only, check_retired_paths=False).errors
    assert any(
        "cannot be promoted with TLAPS evidence alone" in error for error in errors
    )

    legacy_schema = copy.deepcopy(ledger)
    legacy_schema["schema_version"] = 1
    errors = module.validate_ledger(
        legacy_schema,
        check_retired_paths=False,
    ).errors
    assert "proof ledger schema_version must equal 2" in errors


def test_cross_tool_tla_inherited_providers_are_exact() -> None:
    """Cross-tool evidence resolves physical providers through EXTENDS."""

    module = load_checker()
    expected = {
        "effective-lock-body-acquisition-production-refinement": (
            "SumeragiV2AsyncRankAndInitProofs",
            "SumeragiV2AsyncStage4RefinementProofs",
            "SumeragiV2AsyncStage4RefinementProofs",
        ),
        "progress-witness-production-refinement": (
            "SumeragiV2AsyncRankAndInitProofs",
            "SumeragiV2AsyncTemporalClosureProofs",
            "SumeragiV2AsyncTemporalClosureProofs",
        ),
    }
    for contract in module.CROSS_TOOL_REFINEMENT_CONTRACTS[:2]:
        closure = module._cross_tool_tla_module_closure(
            module.FORMAL_DIR, contract.module
        )
        premise = contract.tla_statement.split(" => ", maxsplit=1)[0]
        premise_declaration = module._cross_tool_tla_declaration(
            closure, premise, kind="operator"
        )
        ledger_declaration = module._cross_tool_tla_declaration(
            closure,
            contract.ledger_symbol,
            kind=contract.ledger_declaration_kind,
        )
        theorem_declaration = module._cross_tool_tla_declaration(
            closure, contract.tla_theorem, kind="theorem"
        )
        assert premise_declaration is not None
        assert ledger_declaration is not None
        assert theorem_declaration is not None
        assert (
            premise_declaration[0],
            ledger_declaration[0],
            theorem_declaration[0],
        ) == expected[contract.obligation_id]


def test_cross_tool_promotion_rejects_vacuity_kernel_only_and_missing_call_sites() -> None:
    module = load_checker()
    contracts = module.CROSS_TOOL_REFINEMENT_CONTRACTS
    obligation = contracts[0]
    claim = obligation.claims[0]
    assert claim.verified_kernel is not None
    assert claim.theorem_kernel_projection is not None
    assert claim.verus_requires is not None

    def errors_for(mutated_claim):
        mutated_obligation = replace(
            obligation,
            claims=(mutated_claim, *obligation.claims[1:]),
        )
        return module._cross_tool_promotion_contract_errors(
            (mutated_obligation, *contracts[1:])
        )

    errors = errors_for(replace(claim, verus_ensures="true"))
    assert any("vacuous or constant Verus ensures clause" in error for error in errors)

    errors = errors_for(replace(claim, verus_ensures=claim.verus_requires))
    assert any("must not restate its exact requires clause" in error for error in errors)

    exact_kernel_only = (
        f"{claim.verified_kernel}({claim.theorem_kernel_projection})"
    )
    errors = errors_for(replace(claim, verus_ensures=exact_kernel_only))
    assert any(
        "reviewed nontrivial postcondition beyond its kernel" in error
        for error in errors
    )

    errors = errors_for(replace(claim, production_call_sites=()))
    assert any("no authoritative production kernel call sites" in error for error in errors)

    call_site = claim.production_call_sites[0]
    errors = errors_for(
        replace(
            claim,
            production_call_sites=(
                replace(
                    call_site,
                    item_token_sha256=None,
                    unfrozen_reason=None,
                ),
            ),
        )
    )
    assert any("lacks an exact item token seal" in error for error in errors)

    errors = errors_for(
        replace(
            claim,
            production_call_sites=(
                replace(call_site, item_token_sha256="0" * 63),
            ),
        )
    )
    assert any("invalid exact item token seal" in error for error in errors)


def total_gate_claim(module, constant: str):
    """Return one canonical total checked-gate claim by TLA constant."""

    return next(
        claim
        for contract in module.CROSS_TOOL_REFINEMENT_CONTRACTS
        for claim in contract.claims
        if claim.constant == constant
    )


def ingress_auxiliary(module, kernel: str):
    """Return the ingress claim and one exact auxiliary kernel view."""

    claim = total_gate_claim(
        module,
        "ProductionIngressIdentityAndClassTraceRefinesProtectedOwnership",
    )
    views = module._cross_tool_kernel_views(claim)
    assert len(views) == 4
    matching = tuple(view for view in views if view.verified_kernel == kernel)
    assert len(matching) == 1
    return claim, matching[0]


def materialization_auxiliary(module):
    """Return the ingress reservation-materialization auxiliary view."""

    return ingress_auxiliary(
        module,
        "production_ingress_reservation_materialization_refines_"
        "protected_ownership_kernel",
    )


def leader_wire_auxiliary(module):
    """Return the ingress claim and its durable leader-wire auxiliary view."""

    return ingress_auxiliary(
        module,
        "production_leader_wire_admission_refines_lifecycle_ownership_kernel",
    )


def effect_candidate_auxiliary(module):
    """Return the ingress claim and concrete effect/candidate bridge."""

    return ingress_auxiliary(
        module,
        "production_effect_to_candidate_refines_async_ownership_kernel",
    )


def test_total_checked_gate_contract_cardinality_and_payload_schema() -> None:
    """Thirteen total claims own exactly eighteen distinct checked gates."""

    module = load_checker()
    assert module.CROSS_TOOL_EVIDENCE_SCHEMA_VERSION == 4
    claims = [
        claim
        for contract in module.CROSS_TOOL_REFINEMENT_CONTRACTS
        for claim in contract.claims
    ]
    assert sum(claim.proof_mode == "legacy_requires_builder" for claim in claims) == 4
    assert sum(claim.proof_mode == "total_checked_gate" for claim in claims) == 13
    assert tuple(
        claim.constant
        for claim in claims
        if claim.proof_mode == "legacy_requires_builder"
    ) == module._LEGACY_EFFECTIVE_LOCK_CLAIM_CONSTANTS
    assert tuple(
        claim.constant
        for claim in claims
        if claim.proof_mode == "total_checked_gate"
    ) == tuple(module._TOTAL_GATE_BY_CLAIM)
    gates = [
        view.total_gate
        for claim in claims
        if claim.proof_mode == "total_checked_gate"
        for view in module._cross_tool_kernel_views(claim)
    ]
    assert len(gates) == 18
    assert len({gate.name for gate in gates}) == 18

    claim = total_gate_claim(
        module, "ProductionDurableIntentTraceRefinesProgressWitness"
    )
    document = module._cross_tool_claim_contract_document(claim)
    assert document["proof_mode"] == "total_checked_gate"
    assert document["total_gate"]["name"] == (
        "check_production_durable_intent_transition"
    )
    assert document["verus_requires"] == ""
    assert document["theorem_projection_builder"] is None


