def test_successor_production_source_mapping_mutations_fail_closed(
    tmp_path: Path,
    relative_path: str,
    region_marker: str,
    old: str,
    new: str,
    error_fragment: str,
) -> None:
    module = load_checker()
    required_sources = (
        "crates/iroha_core/src/sumeragi/v2_runner.rs",
        "crates/iroha_core/src/sumeragi/status.rs",
        "crates/iroha_core/src/sumeragi/v2.rs",
        "crates/iroha_core/src/sumeragi/v2_runtime.rs",
        "crates/iroha_core/src/sumeragi/v2_block_sync.rs",
        "crates/iroha_core/src/sumeragi/v2_effects.rs",
        "crates/iroha_core/src/sumeragi/v2_recovery.rs",
        "scripts/run_sumeragi_v2_release_gates.sh",
    )
    for source_name in required_sources:
        destination = tmp_path / source_name
        destination.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(ROOT_DIR / source_name, destination)

    assert module._successor_production_source_fidelity_errors(tmp_path) == []

    path = tmp_path / relative_path
    source = path.read_text(encoding="utf-8")
    region_start = source.find(region_marker)
    assert region_start >= 0
    mutation = source.find(old, region_start)
    assert mutation >= 0
    function_name = re.search(r"\bfn\s+([A-Za-z_][A-Za-z0-9_]*)", region_marker)
    if function_name is not None:
        owning_items = []
        for item in module.rust_items(source, function_name.group(1)):
            item_start = source.find(item.source)
            if item_start <= region_start < item_start + len(item.source):
                owning_items.append((item_start, item))
        assert len(owning_items) == 1, (
            "region marker did not select exactly one production Rust item",
            relative_path,
            region_marker,
        )
        item_start, item = owning_items[0]
        assert item_start <= mutation < item_start + len(item.source), (
            "mutation escaped the production Rust item selected by its region marker",
            relative_path,
            region_marker,
            old,
        )
    path.write_text(
        source[:mutation] + new + source[mutation + len(old) :],
        encoding="utf-8",
    )

    errors = module._successor_production_source_fidelity_errors(tmp_path)
    assert any(error_fragment in error for error in errors), errors


def test_locked_body_reproposal_source_fidelity_rejects_formal_and_production_mutants(
    tmp_path: Path,
) -> None:
    """The justified-high obligation must remain connected through admission."""

    module = load_checker()
    assert module._locked_body_reproposal_source_fidelity_errors(
        module.FORMAL_DIR, ROOT_DIR
    ) == []

    formal_names = (
        "SumeragiV2Core.tla",
        "SumeragiV2InductiveProofs.tla",
    )
    production_names = (
        "crates/iroha_core/src/sumeragi/v2_core/reducer.rs",
        "crates/iroha_core/src/sumeragi/v2_core/wal.rs",
        "crates/iroha_core/src/sumeragi/v2.rs",
        "crates/iroha_core/src/sumeragi/v2_effects.rs",
        "crates/iroha_core/src/sumeragi/v2_runner.rs",
        "crates/iroha_core/src/sumeragi/v2_candidate.rs",
    )

    def copy_fixture(case: str) -> tuple[Path, Path]:
        repo_root = tmp_path / case
        formal_dir = repo_root / "docs" / "formal" / "sumeragi_v2"
        formal_dir.mkdir(parents=True)
        for name in formal_names:
            shutil.copy2(module.FORMAL_DIR / name, formal_dir / name)
        for name in production_names:
            destination = repo_root / name
            destination.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(ROOT_DIR / name, destination)
        return repo_root, formal_dir

    formal_mutants = (
        (
            "vacuous_guard",
            "SumeragiV2Core.tla",
            "operator",
            "LocalProposalReproposesJustifiedHigh",
            "\\/ proposal.subject = proposal.justifySubject",
            "\\/ TRUE",
            "exact justified-high subject contract",
        ),
        (
            "disconnected_guard",
            "SumeragiV2Core.tla",
            "operator",
            "BeginLocalProposal",
            "LocalProposalReproposesJustifiedHigh(proposal)",
            "TRUE",
            "must enforce the exact justified-high subject guard",
        ),
        (
            "tautological_theorem",
            "SumeragiV2InductiveProofs.tla",
            "theorem",
            "BeginLocalProposalReproposesExactJustifiedHigh",
            "IN \\/ justification.rank = NoRank\n"
            "            \\/ subject = justification.subject",
            "IN TRUE",
            "exact nontrivial justified-high subject postcondition",
        ),
    )
    for (
        case,
        filename,
        declaration_kind,
        symbol,
        old,
        new,
        error_fragment,
    ) in formal_mutants:
        repo_root, formal_dir = copy_fixture(case)
        path = formal_dir / filename
        source = path.read_text(encoding="utf-8")
        if declaration_kind == "operator":
            mutated = mutate_tla_operator(source, symbol, old, new)
        else:
            mutated = mutate_tla_theorem(source, symbol, old, new)
        path.write_text(mutated, encoding="utf-8")
        errors = module._locked_body_reproposal_source_fidelity_errors(
            formal_dir, repo_root
        )
        assert any(error_fragment in error for error in errors), errors

    rust_mutants = (
        (
            "replay_skips_safe_value_authorization",
            "crates/iroha_core/src/sumeragi/v2_core/reducer.rs",
            "on_resume_after_replay",
            ".filter(|proposal| Self::durable_proposal_is_active(&self.durable, proposal))",
            ".filter(|_| true)",
            "replay proposal authorization boundary",
        ),
        (
            "durable_proposal_disconnects_safe_value",
            "crates/iroha_core/src/sumeragi/v2_core/reducer.rs",
            "durable_proposal_is_active",
            "&& Self::proposal_is_safe_for_durable_lock(durable, proposal)",
            "&& true",
            "durable proposal replay authorization kernel",
        ),
        (
            "shared_safe_value_changes_subject_projection",
            "crates/iroha_core/src/sumeragi/v2_core/reducer.rs",
            "proposal_is_safe_for_durable_lock",
            "if locked.subject() == subject {",
            "if locked.subject() != subject {",
            "shared live-and-replay safe-value kernel",
        ),
        (
            "live_safe_value_returns_constant",
            "crates/iroha_core/src/sumeragi/v2_core/reducer.rs",
            "safe_to_prepare",
            "Self::proposal_is_safe_for_durable_lock(&self.durable, proposal)",
            "true",
            "live proposal safe-value call path",
        ),
        (
            "runner_replay_owner_ignores_locked_subject",
            "crates/iroha_core/src/sumeragi/v2_runner.rs",
            "from_replayed_proposal",
            "&& replayed.subject == locked_subject",
            "&& true",
            "exact replayed-proposal lock-owner authorization kernel",
        ),
        (
            "runner_replay_projection_drops_subject",
            "crates/iroha_core/src/sumeragi/v2_runner.rs",
            "replayed_proposal_sign",
            "subject: proposal.subject,",
            "subject: wire::BlockSubject::default(),",
            "replayed proposal tag/round/subject projection",
        ),
        (
            "runner_startup_disconnects_replay_owner",
            "crates/iroha_core/src/sumeragi/v2_runner.rs",
            "run_inner",
            "LocalProposalState::from_replayed_proposal(replayed_proposal, initial_directive)",
            "LocalProposalState::from_replayed_proposal(None, initial_directive)",
            "startup replay-owner handoff",
        ),
        (
            "executor_skips_one_shot_producer_reservation",
            "crates/iroha_core/src/sumeragi/v2_effects.rs",
            "can_schedule_local_proposal",
            "self.runtime\n            .local_proposal_admission_available(tag)\n            .map_err(EffectExecutorError::Runtime)",
            "Ok(true)",
            "serialized active-view one-shot producer reservation",
        ),
        (
            "runner_replacement_bypasses_one_shot_producer_reservation",
            "crates/iroha_core/src/sumeragi/v2_runner.rs",
            "schedule_local_proposal",
            "executor.can_schedule_local_proposal()?",
            "executor.can_admit_local_proposal()",
            "every locked-load and fresh candidate observation must retain the serialized one-shot producer gate",
        ),
        (
            "wal_high_subject",
            "crates/iroha_core/src/sumeragi/v2_core/wal.rs",
            "apply_in_place",
            "highest.subject() == proposal.manifest().subject()",
            "highest.subject() != proposal.manifest().subject()",
            "Timeout justification high certificate",
        ),
        (
            "wal_lock_promotion",
            "crates/iroha_core/src/sumeragi/v2_core/wal.rs",
            "apply_in_place",
            "None => self.locked = Some(highest.clone()),",
            "None => {},",
            "InstallTimeout must promote",
        ),
        (
            "directive_projection",
            "crates/iroha_core/src/sumeragi/v2.rs",
            "local_proposal_directive",
            """let locked_subject = locked
            .map(|certificate| self.registry.subject(certificate.subject()))
            .transpose()?;""",
            "let locked_subject = None;",
            "runner directive must project",
            ),
            (
                "runner_fresh_fallback",
                "crates/iroha_core/src/sumeragi/v2_runner.rs",
                "schedule_local_proposal",
                "if directive.locked_body().is_some() {",
                "if directive.locked_body().is_none() {",
                "locked directive must never fall through",
            ),
            (
                "runner_subject_mismatch",
                "crates/iroha_core/src/sumeragi/v2_runner.rs",
                "encode_exact_local_body",
                "locked_subject.is_some_and(|locked| locked != subject)",
                "locked_subject.is_some_and(|locked| locked == subject)",
                "subject differs from the durable lock",
            ),
        (
            "runner_disconnected_admission",
            "crates/iroha_core/src/sumeragi/v2_runner.rs",
            "submit_encoded_body",
            "executor.admit_local_proposal(owner.tag, manifest, canonical_wire, services)?;",
            "drop((owner.tag, manifest, canonical_wire, services));",
            "encoded proposal admission must preserve",
        ),
        (
            "candidate_accepts_lock",
            "crates/iroha_core/src/sumeragi/v2_candidate.rs",
            "validate_request",
            "if request.directive.locked_subject().is_some() {",
            "if request.directive.locked_subject().is_none() {",
            "fresh candidate construction must reject",
        ),
    )
    for case, relative, item, old, new, error_fragment in rust_mutants:
        repo_root, formal_dir = copy_fixture(case)
        mutate_rust_item_source(module, repo_root / relative, item, old, new)
        errors = module._locked_body_reproposal_source_fidelity_errors(
            formal_dir, repo_root
        )
        assert any(error_fragment in error for error in errors), errors

    repo_root, formal_dir = copy_fixture("directive_fields_exposed")
    directive_path = repo_root / "crates/iroha_core/src/sumeragi/v2.rs"
    directive_source = directive_path.read_text(encoding="utf-8")
    private_struct = """pub(crate) struct LocalProposalDirective {
    tag: reducer::EventTag,
    leader: wire::ValidatorIndex,
    locked_round: Option<wire::ConsensusRound>,
    locked_subject: Option<wire::BlockSubject>,
    decided_subject: Option<wire::BlockSubject>,
}"""
    exposed_struct = private_struct.replace(
        "    tag: reducer::EventTag,",
        "    pub(crate) tag: reducer::EventTag,",
        1,
    )
    assert directive_source.count(private_struct) == 1
    directive_path.write_text(
        directive_source.replace(
            private_struct,
            exposed_struct,
            1,
        ),
        encoding="utf-8",
    )
    errors = module._locked_body_reproposal_source_fidelity_errors(
        formal_dir, repo_root
    )
    assert any(
        "LocalProposalDirective production fields must remain private" in error
        for error in errors
    ), errors

    repo_root, formal_dir = copy_fixture("directive_test_constructor_exposed")
    directive_path = repo_root / "crates/iroha_core/src/sumeragi/v2.rs"
    directive_source = directive_path.read_text(encoding="utf-8")
    test_only_constructor = (
        "    #[cfg(test)]\n"
        "    pub(crate) const fn for_test("
    )
    assert directive_source.count(test_only_constructor) == 1
    directive_path.write_text(
        directive_source.replace(
            test_only_constructor,
            "    pub(crate) const fn for_test(",
            1,
        ),
        encoding="utf-8",
    )
    errors = module._locked_body_reproposal_source_fidelity_errors(
        formal_dir, repo_root
    )
    assert any(
        "test-only exact local-proposal directive constructor must have "
        "exact reviewed attributes" in error
        for error in errors
    ), errors


