def test_serve_lifecycle_contract_rejects_missing_operator_and_arbitrary_budget(
    tmp_path: Path,
) -> None:
    """The lasso repair cannot lose ownership state or restore a proof parameter."""

    module = load_checker()
    for module_name, operators in module.SERVE_LIFECYCLE_REQUIRED_OPERATORS.items():
        declarations = []
        for operator in operators:
            required = module.SERVE_LIFECYCLE_REQUIRED_OPERATOR_TOKENS.get(
                (module_name, operator),
                (),
            )
            body = "  /\\ lifecycleState # {}"
            if required:
                body += "".join(f"\n  /\\ {token}" for token in required)
            required_sequences = (
                module.SERVE_LIFECYCLE_REQUIRED_OPERATOR_TOKEN_SEQUENCES.get(
                    (module_name, operator),
                    (),
                )
            )
            if required_sequences:
                body += "".join(
                    f"\n  /\\ {sequence}"
                    for sequence in required_sequences
                )
            declarations.append(f"{operator} ==\n{body}")
        declaration_source = "\n\n".join(declarations)
        (tmp_path / f"{module_name}.tla").write_text(
            f"---- MODULE {module_name} ----\n\n"
            f"{declaration_source}\n\n"
            "====\n",
            encoding="utf-8",
        )

    assert module._serve_lifecycle_temporal_contract_errors(tmp_path) == []

    async_module = "SumeragiV2AsyncNetwork"
    async_path = tmp_path / f"{async_module}.tla"
    async_source = async_path.read_text(encoding="utf-8")
    async_path.write_text(
        mutate_tla_operator(
            async_source,
            "ReserveExactServeCapacity",
            "ReserveExactServeCapacityVia",
            "WeakenedReserveExactServeCapacityVia",
        ),
        encoding="utf-8",
    )
    errors = module._serve_lifecycle_temporal_contract_errors(tmp_path)
    assert any(
        "ReserveExactServeCapacity" in error
        and "ReserveExactServeCapacityVia" in error
        for error in errors
    ), errors

    async_path.write_text(
        mutate_tla_operator(
            async_source,
            "AdvanceExactServeCapacityVia",
            (
                "asyncNextServeAdmissionOrdinal' = "
                "[asyncNextServeAdmissionOrdinal EXCEPT ![node] = @ + 1]"
            ),
            "asyncNextServeAdmissionOrdinal' = asyncNextServeAdmissionOrdinal",
        ),
        encoding="utf-8",
    )
    errors = module._serve_lifecycle_temporal_contract_errors(tmp_path)
    assert any(
        "AdvanceExactServeCapacityVia" in error
        and "reviewed structural dependencies" in error
        for error in errors
    ), errors
    async_path.write_text(async_source, encoding="utf-8")

    exact_module = "SumeragiV2ExactDecisionStageServiceClosureProofs"
    exact_path = tmp_path / f"{exact_module}.tla"
    exact_source = exact_path.read_text(encoding="utf-8")
    rank = "ExactDecisionRequestLifecycleIngressRank"
    exact_path.write_text(
        exact_source.replace(rank, f"{rank}Weakened", 1),
        encoding="utf-8",
    )
    errors = module._serve_lifecycle_temporal_contract_errors(tmp_path)
    assert any(
        f"missing required Serve lifecycle operator {rank}" in error
        for error in errors
    ), errors

    exact_path.write_text(
        exact_source.replace(
            "lifecycleState # {}",
            "producerBudget = producerBudget",
            1,
        ),
        encoding="utf-8",
    )
    errors = module._serve_lifecycle_temporal_contract_errors(tmp_path)
    assert any(
        "may not use an arbitrary producerBudget" in error for error in errors
    ), errors

    exact_path.write_text(
        exact_source.replace(
            "lifecycleState # {}",
            (
                "ExactDecisionRequestLifecycleOwnedFairAction "
                "= ExactDecisionRequestLifecycleOwnedFairAction"
            ),
            1,
        ),
        encoding="utf-8",
    )
    errors = module._serve_lifecycle_temporal_contract_errors(tmp_path)
    assert any(
        "retired synthetic-fairness symbol" in error
        and "ExactDecisionRequestLifecycleOwnedFairAction" in error
        for error in errors
    ), errors

    exact_path.write_text(
        mutate_tla_operator(
            exact_source,
            "ExactDecisionRequestLifecycleRankDescentProperty",
            "ExactDecisionRequestLifecycleConcreteActionOriginProperty",
            (
                "WeakenedConcreteActionOriginPropertySuffix "
                '/\\ "ExactDecisionRequestLifecycleConcreteActionOriginProperty"'
            ),
        ),
        encoding="utf-8",
    )
    errors = module._serve_lifecycle_temporal_contract_errors(tmp_path)
    assert any(
        "ExactDecisionRequestLifecycleRankDescentProperty" in error
        and "ExactDecisionRequestLifecycleConcreteActionOriginProperty" in error
        for error in errors
    ), errors

    adequate_module = "SumeragiV2AdequateLeaderServiceClosureProofs"
    adequate_path = tmp_path / f"{adequate_module}.tla"
    adequate_source = adequate_path.read_text(encoding="utf-8")
    adequate_path.write_text(
        mutate_tla_operator(
            adequate_source,
            "AdequateLeaderTargetNonDescentEpisodeBudget",
            "Cardinality",
            "0",
        ),
        encoding="utf-8",
    )
    errors = module._serve_lifecycle_temporal_contract_errors(tmp_path)
    assert any(
        "AdequateLeaderTargetNonDescentEpisodeBudget" in error
        and "Cardinality" in error
        for error in errors
    ), errors

    adequate_path.write_text(
        mutate_tla_operator(
            adequate_source,
            "AdequateLeaderTargetComposedRankDescentProperty",
            "AdequateLeaderTargetProducerTransportOccurrenceClosureProperty",
            "AdequateLeaderTargetRankDescentProperty",
        ),
        encoding="utf-8",
    )
    errors = module._serve_lifecycle_temporal_contract_errors(tmp_path)
    assert any(
        "AdequateLeaderTargetComposedRankDescentProperty" in error
        and (
            "AdequateLeaderTargetProducerTransportOccurrenceClosureProperty"
            in error
            or "AdequateLeaderTargetRankDescentProperty" in error
        )
        for error in errors
    ), errors


